import {storyDossier} from './story-campaign.js';
import {MISSIONS,BOSS_CATALOG,getMission,getBoss,missionScaling} from './campaign.js?v=0.29.0';
import {normalizeCampaign,missionAccess} from './campaign-progress.js?v=0.29.0';

const escape=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const enemyNames={walker:'거리 감염자',runner:'질주 감염자',shield:'방패 감염자',screamer:'비명 감염자',gas:'가스 감염자',crawler:'기어다니는 감염자',brute:'거대 감염자',spitter:'독액 감염자'};
const clock=value=>`${Math.floor(value/60)}:${String(Math.floor(value%60)).padStart(2,'0')}`;
const portrait=(boss,large=false)=>`<canvas class="boss-portrait${large?' large':''}" data-boss-portrait="${escape(boss.id)}" width="240" height="240" role="img" aria-label="${escape(boss.name)} 보스 모습"></canvas>`;
const heading=(label,title,description)=>`<div class="dialog-header"><div><p class="eyebrow">${label}</p><h2>${title}</h2><p>${description}</p></div><button type="button" class="close-button" data-action="close" aria-label="닫기">×</button></div>`;

export function campaignMapHTML(raw,selectedId){
  const progress=normalizeCampaign(raw),selected=getMission(selectedId)||getMission(progress.selectedMission),access=missionAccess(progress,selected.id),scale=missionScaling(selected.index);
  const mid=getBoss(selected.midBoss),final=getBoss(selected.finalBoss);
  return `<section class="panel campaign-panel">${heading('CITY CAMPAIGN / 12 MISSIONS','감염 도시 작전 지도','미션을 순서대로 돌파하세요. 모든 미션에는 중간보스와 최종보스가 있습니다.')}<div class="campaign-summary"><span class="badge gold">${progress.cleared.length} / ${MISSIONS.length} 구역 확보</span><span>뒤로 갈수록 적과 보스가 강해집니다.</span></div><div class="campaign-layout"><div class="mission-map" role="group" aria-label="미션 선택">${MISSIONS.map(mission=>{const item=missionAccess(progress,mission.id);return `<button type="button" class="mission-node ${item.cleared?'cleared':''} ${mission.id===selected.id?'selected':''} ${item.unlocked?'':'locked'}" data-action="mission-select" data-value="${mission.id}" aria-pressed="${mission.id===selected.id}" ${item.unlocked?'':'disabled'} style="--mission-accent:${mission.accent}"><span class="mission-number">${String(mission.index+1).padStart(2,'0')}</span><span><strong>${escape(mission.title)}</strong><small>${escape(mission.subtitle)}</small></span><span class="mission-lock">${item.cleared?'✓':item.unlocked?'→':'잠금'}</span></button>`;}).join('')}</div><article class="mission-dossier" style="--mission-accent:${selected.accent}"><p class="eyebrow">MISSION ${String(selected.index+1).padStart(2,'0')}</p><h3>${escape(selected.title)}</h3><p>${escape(selected.subtitle)}</p>${storyDossier(selected.id,{cleared:access.cleared,escape})}<div class="mission-threat"><span>적 체력 <strong>×${scale.hp.toFixed(2)}</strong></span><span>공격력 <strong>×${scale.damage.toFixed(2)}</strong></span><span>출현 빈도 <strong>×${scale.spawn.toFixed(2)}</strong></span></div><button type="button" class="primary mission-prepare" data-action="mission-prepare" data-value="${selected.id}" ${access.unlocked?'':'disabled'}>이 미션 출격 준비 ↗</button><p class="mission-enemies">주요 적: ${selected.enemyPool.map(item=>enemyNames[item.type]||escape(item.type)).join(' · ')}</p><div class="mission-bosses">${[[mid,'중간보스'],[final,'최종보스']].map(([boss,role])=>`<button type="button" class="mission-boss" data-action="boss-detail" data-value="${boss.id}">${portrait(boss)}<span class="boss-role">${role}</span><strong>${escape(boss.name)}</strong><small>${escape(boss.skillName)}</small></button>`).join('')}</div><p class="mission-rule">중간보스를 처치해야 최종보스가 출현합니다. 두 보스를 모두 처치하면 다음 맵이 열립니다.</p>${access.bestTime!==null?`<p class="success">최고 기록 ${clock(access.bestTime)}</p>`:''}</article></div><div class="panel-actions"><button class="ghost" data-action="legacy">도시 탈출 작전</button><button class="secondary" data-action="codex">보스 도감</button></div></section>`;
}

export function bossCodexHTML(raw,selectedKey){
  const progress=normalizeCampaign(raw),selected=getBoss(selectedKey)||BOSS_CATALOG[0],mission=getMission(selected.missionId),scale=missionScaling(mission.index),seen=progress.bossSeen.includes(selected.id),defeated=progress.bossDefeated.includes(selected.id);
  return `<section class="panel codex-panel">${heading('FIELD INTELLIGENCE / BOSS ARCHIVE','보스 도감','외형과 고유 스킬, 피하는 방법을 확인하고 다음 전투를 준비하세요.')}<div class="campaign-summary"><span class="badge gold">${progress.bossSeen.length} / ${BOSS_CATALOG.length} 조우</span><span>${progress.bossDefeated.length}종 처치</span></div><div class="codex-layout"><div class="boss-roster" role="group" aria-label="보스 선택">${BOSS_CATALOG.map(boss=>`<button type="button" class="boss-roster-card ${boss.id===selected.id?'selected':''}" data-action="boss-detail" data-value="${boss.id}" aria-pressed="${boss.id===selected.id}">${portrait(boss)}<strong>${escape(boss.name)}</strong><small>${getMission(boss.missionId).index+1}탄 · ${boss.role==='mid'?'중간':'최종'}</small><span class="boss-record ${progress.bossDefeated.includes(boss.id)?'defeated':''}">${progress.bossDefeated.includes(boss.id)?'처치 완료':progress.bossSeen.includes(boss.id)?'조우 기록':'미조우'}</span></button>`).join('')}</div><article class="boss-dossier" style="--mission-accent:${selected.palette.accent}"><div class="boss-dossier-art">${portrait(selected,true)}<span class="boss-record ${defeated?'defeated':''}">${defeated?'처치 완료':seen?'조우 기록':'미조우'}</span></div><p class="eyebrow">MISSION ${String(mission.index+1).padStart(2,'0')} / ${selected.role==='mid'?'MID BOSS':'FINAL BOSS'}</p><h3>${escape(selected.name)}</h3><p class="boss-title">${escape(selected.title)}</p><p>${escape(selected.appearance.description)}</p><div class="boss-stat-line"><span>체력 <strong>${Math.ceil(selected.stats.hp*scale.hp)}</strong></span><span>접촉 피해 <strong>${Math.ceil(selected.stats.damage*scale.damage)}</strong></span></div><div class="boss-skill"><span>고유 스킬</span><h4>${escape(selected.skillName)}</h4><p>${escape(selected.skillDescription)}</p></div><div class="boss-counter"><span>대응 방법</span><p>${escape(selected.counter)}</p></div><button class="secondary" data-action="campaign">작전 지도로</button></article></div></section>`;
}
